begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select plan(10);
select set_config('test.hang', '{"body":{"x":0,"y":0,"z":0,"rotationX":0,"rotationY":0,"rotationZ":0,"scale":1},"objects":[{"id":"00000000-0000-4000-8000-000000000001","name":"Pull-up bar","slug":"pull-up-bar","x":0,"y":0,"z":0,"rotationX":0,"rotationY":0,"rotationZ":0,"scale":1,"attachment":"both","pulleyHeight":1.5,"gripOffsets":{"left":{"x":0.02,"y":0,"z":0}}}]}', true);
select set_config('test.bench', '{"id":"00000000-0000-4000-8000-000000000002","name":"Adjustable bench","slug":"bench","x":1,"y":0,"z":0,"rotationX":0,"rotationY":0,"rotationZ":0,"scale":1,"attachment":"none","pulleyHeight":1.5}', true);
select set_config('test.dumbbell', '{"id":"00000000-0000-4000-8000-000000000003","name":"Dumbbell","slug":"dumbbell","x":1,"y":0.65,"z":0,"rotationX":0,"rotationY":0,"rotationZ":0,"scale":1,"attachment":"left","pulleyHeight":1.5}', true);
select ok(private.valid_studio_layout(current_setting('test.hang')::jsonb), 'both hands can hang from the bar with a custom grip');
select ok(private.valid_studio_layout(jsonb_set(current_setting('test.hang')::jsonb, '{objects,0,attachment}', '"none"')), 'the bar can stand unused');
select ok(not private.valid_studio_layout(jsonb_set(current_setting('test.hang')::jsonb, '{objects,0,attachment}', '"left"')), 'one hand cannot hold the bar');
select ok(not private.valid_studio_layout(jsonb_set(current_setting('test.hang')::jsonb, '{objects,0,machineUse}', 'true')), 'the bar is not a machine');
select ok(not private.valid_studio_layout(jsonb_set(jsonb_set(current_setting('test.hang')::jsonb, '{objects,1}', current_setting('test.bench')::jsonb), '{seating}', '{"benchId":"00000000-0000-4000-8000-000000000002","facing":"front"}')), 'hanging excludes bench seating');
select ok(not private.valid_studio_layout(jsonb_set(current_setting('test.hang')::jsonb, '{supports}', '[{"region":"left-foot","objectId":null,"surface":"floor","point":{"x":0,"y":0,"z":0},"normal":{"x":0,"y":1,"z":0},"turn":0}]')), 'hanging excludes surface supports');
select ok(not private.valid_studio_layout(jsonb_set(current_setting('test.hang')::jsonb, '{objects,1}', current_setting('test.dumbbell')::jsonb)), 'a hanging hand cannot also hold a weight');
select ok(private.valid_studio_layout(jsonb_set(jsonb_set(current_setting('test.hang')::jsonb, '{objects,0,attachment}', '"none"'), '{objects,1}', current_setting('test.dumbbell')::jsonb)), 'weights stay usable beside an unused bar');
select ok(has_function_privilege('authenticated', 'private.valid_studio_layout_before_pull_up_bar(jsonb)', 'execute') and not has_function_privilege('anon', 'private.valid_studio_layout_before_pull_up_bar(jsonb)', 'execute'), 'the previous validator keeps its grants');
select is((select count(*)::integer from public.equipment where slug = 'pull-up-bar'), 1, 'one normalized equipment record');
select * from finish();
rollback;
